"use client";

import * as React from "react";
import { ArrowUp } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * CLARIFYING QUESTION: the agent pauses to ask
 *
 *   asking    the question and its options; press 1–9 or click
 *   other     "Something else" turns into a field in place
 *   multiple  options toggle (their checks draw themselves), then
 *             "Continue · 3", the count rolling as you pick
 *   answered  the same card folds into one line: the options close,
 *             "Needs your answer" lifts away and the question and
 *             your answer slide into its place as a check draws
 *   skipped   "Skipped, the agent will decide"
 *
 * Pair it with a client-side tool that has no execute: render it
 * for the tool's input and send the answer back as the output.
 * ───────────────────────────────────────────────────────── */

export interface QuestionOption {
  id: string;
  label: string;
  description?: string;
}

export interface QuestionAnswer {
  ids: string[];
  labels: string[];
  /** What they typed under "Something else". */
  other?: string;
}

export interface ClarifyingQuestionProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onSubmit"
> {
  question: string;
  detail?: string;
  options: QuestionOption[];
  /** Allow several answers, confirmed with Continue. */
  multiple?: boolean;
  /** Offer "Something else" with a field. */
  allowOther?: boolean;
  otherLabel?: string;
  /** The answer once given, e.g. the tool's output; shows the folded line. */
  answer?: QuestionAnswer | null;
  onAnswer: (answer: QuestionAnswer) => void;
  /** Shows Skip; the agent continues with its own choice. */
  onSkip?: () => void;
  skipped?: boolean;
  skippedText?: string;
  autoFocus?: boolean;
}

const OTHER = "__other__";
const EASE = "cubic-bezier(0.23,1,0.32,1)";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** A piece of a line that opens out of nothing and folds back into it. */
function Reveal({
  show,
  reduced,
  className = "",
  children,
}: {
  show: boolean;
  reduced: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <span
      aria-hidden={!show || undefined}
      className={`grid ${className}`}
      style={{
        gridTemplateColumns: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        filter: show ? "none" : "blur(3px)",
        transition: reduced
          ? "none"
          : `grid-template-columns 460ms ${MORPH}, opacity ${show ? "320ms" : "160ms"} ${MORPH}, filter 320ms ${MORPH}`,
      }}
    >
      <span className="min-w-0 truncate [clip-path:inset(-4px_-2px)]">
        {children}
      </span>
    </span>
  );
}

function DrawnCheck({
  drawn,
  reduced,
  className = "size-3",
}: {
  drawn: boolean;
  reduced: boolean;
  className?: string;
}) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className={className}>
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2.4"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 320ms ${MORPH} 60ms`
              : "none",
        }}
      />
    </svg>
  );
}

export function ClarifyingQuestion({
  question,
  detail,
  options,
  multiple = false,
  allowOther = true,
  otherLabel = "Something else",
  answer,
  onAnswer,
  onSkip,
  skipped = false,
  skippedText = "the agent will decide",
  autoFocus = false,
  className = "",
  ...props
}: ClarifyingQuestionProps) {
  const id = React.useId();
  const reduced = useReducedMotion();
  const [own, setOwn] = React.useState<QuestionAnswer | null>(null);
  const [ownSkipped, setOwnSkipped] = React.useState(false);
  const [picked, setPicked] = React.useState<string[]>([]);
  const [otherOpen, setOtherOpen] = React.useState(false);
  const [otherText, setOtherText] = React.useState("");
  const [active, setActive] = React.useState(0);
  const [highlight, setHighlight] = React.useState({
    top: 0,
    height: 0,
    ready: false,
  });

  const surfaceRef = React.useRef<HTMLDivElement>(null);
  const rowRefs = React.useRef<(HTMLButtonElement | HTMLDivElement | null)[]>(
    [],
  );
  const otherRef = React.useRef<HTMLInputElement>(null);

  const final = answer ?? own;
  const isSkipped = skipped || ownSkipped;
  const done = Boolean(final) || isSkipped;
  const rows = allowOther
    ? [...options, { id: OTHER, label: otherLabel }]
    : options;

  // The options are about to fold away: keep focus on the card instead of dropping it on the page.
  const fold = () => {
    if (surfaceRef.current?.contains(document.activeElement))
      surfaceRef.current.focus({ preventScroll: true });
  };

  React.useEffect(() => {
    if (autoFocus && !done)
      (rowRefs.current[0] as HTMLElement | null)?.focus({
        preventScroll: true,
      });
    // Autofocus applies only when this question mounts.
  }, []);

  React.useEffect(() => {
    if (otherOpen) otherRef.current?.focus({ preventScroll: true });
  }, [otherOpen]);

  // Digits also answer when nothing else has focus (never while typing in a field).
  const chooseRef = React.useRef<(i: number) => void>(() => {});
  React.useEffect(() => {
    if (done) return;
    const onKey = (e: KeyboardEvent) => {
      const focused = document.activeElement;
      if (
        (focused && focused !== document.body) ||
        e.metaKey ||
        e.ctrlKey ||
        e.altKey ||
        !/^[1-9]$/.test(e.key)
      )
        return;
      if (Number(e.key) > rows.length) return;
      e.preventDefault();
      chooseRef.current(Number(e.key) - 1);
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [done, rows.length]);

  // The highlight slides to the active row and takes its height.
  React.useLayoutEffect(() => {
    const row = rowRefs.current[active];
    if (!row || done) return;
    const measure = () => {
      const top = row.offsetTop;
      const height = row.offsetHeight;
      setHighlight((h) =>
        h.top === top && h.height === height && h.ready
          ? h
          : { top, height, ready: h.height > 0 },
      );
    };
    measure();
    // Descriptions can wrap after a resize or font load without changing selection.
    const observer = new ResizeObserver(measure);
    observer.observe(row);
    if (row.parentElement) observer.observe(row.parentElement);
    return () => observer.disconnect();
  }, [active, otherOpen, done, rows.length]);

  const submit = (picks: string[], other?: string) => {
    const order = (x: string) => options.findIndex((o) => o.id === x);
    const ids = [...picks].sort((a, b) => order(a) - order(b));
    const next: QuestionAnswer = {
      ids,
      labels: ids.map((i) => options.find((o) => o.id === i)?.label ?? i),
      ...(other ? { other } : {}),
    };
    fold();
    if (answer === undefined) setOwn(next);
    onAnswer(next);
  };

  const skip = () => {
    fold();
    setOwnSkipped(true);
    onSkip?.();
  };

  const choose = (i: number) => {
    const row = rows[i];
    if (!row) return;
    setActive(i);
    if (row.id === OTHER) {
      setOtherOpen((o) => (multiple ? !o : true));
      return;
    }
    if (multiple)
      setPicked((p) =>
        p.includes(row.id) ? p.filter((x) => x !== row.id) : [...p, row.id],
      );
    else submit([row.id]);
  };

  React.useLayoutEffect(() => {
    chooseRef.current = choose;
  });

  const submitOther = () => {
    const text = otherText.trim();
    if (!text) return;
    if (multiple) submit(picked, text);
    else submit([], text);
  };

  const onListKey = (e: React.KeyboardEvent) => {
    if (e.target instanceof HTMLInputElement) return;
    if (/^[1-9]$/.test(e.key) && Number(e.key) <= rows.length) {
      e.preventDefault();
      const next = Number(e.key) - 1;
      choose(next);
      // A single answer has already focused the receipt; don't refocus a closing row.
      if (multiple || rows[next].id === OTHER)
        (rowRefs.current[next] as HTMLElement | null)?.focus();
    } else if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      const next =
        (active + (e.key === "ArrowDown" ? 1 : -1) + rows.length) % rows.length;
      setActive(next);
      (rowRefs.current[next] as HTMLElement | null)?.focus();
    }
  };

  const summary = final
    ? [...final.labels, final.other].filter(Boolean).join(", ")
    : "";
  const receipt = isSkipped && !final ? `Skipped, ${skippedText}` : summary;
  const count = picked.length + (otherOpen && otherText.trim() ? 1 : 0);
  const canContinue = count > 0;

  return (
    <div
      ref={surfaceRef}
      tabIndex={-1}
      className={`overflow-hidden rounded-[14px] border border-border bg-background outline-none ${className}`}
      {...props}
    >
      {/* The header stays put; once answered it becomes the whole card: question · answer. */}
      <div
        className="flex min-w-0 items-center text-[12px]"
        style={{
          padding: done ? "13px 16px" : "14px 16px 0",
          transition: reduced ? "none" : `padding 460ms ${MORPH}`,
        }}
      >
        <span
          aria-hidden="true"
          className="relative mr-2 flex size-4 shrink-0 items-center justify-center"
        >
          <span
            className="absolute inset-0 flex items-center justify-center"
            style={swap(!done, reduced)}
          >
            <span className="relative flex size-1.5">
              <span
                className={`absolute inset-0 rounded-full bg-primary motion-reduce:animate-none ${done ? "" : "animate-[ui-ping_1.6s_cubic-bezier(0,0,0.2,1)_infinite]"}`}
              />
              <span className="relative size-1.5 rounded-full bg-primary" />
            </span>
          </span>
          <span
            className="absolute inset-0 flex items-center justify-center rounded-full bg-muted text-muted-foreground"
            style={swap(done, reduced)}
          >
            <DrawnCheck drawn={done} reduced={reduced} className="size-2.5" />
          </span>
        </span>
        <span
          aria-hidden={done || undefined}
          className="shrink-0 text-muted-foreground"
        >
          <TextMorph>{done ? "" : "Needs your answer"}</TextMorph>
        </span>
        <Reveal show={done} reduced={reduced} className="min-w-0">
          <span title={question} className="text-muted-foreground">
            {question}
          </span>
        </Reveal>
        <Reveal show={done} reduced={reduced} className="max-w-[55%] shrink-0">
          <span aria-hidden="true" className="px-2 text-muted-foreground/50">
            ·
          </span>
          <span title={receipt} className="font-medium text-foreground">
            {receipt}
          </span>
        </Reveal>
      </div>
      <span role="status" className="sr-only">
        {done ? `${question}: ${receipt}` : ""}
      </span>

      {/* Everything else folds shut once it's answered. */}
      <div
        inert={done}
        aria-hidden={done || undefined}
        className="grid"
        style={{
          gridTemplateRows: done ? "0fr" : "1fr",
          opacity: done ? 0 : 1,
          transition: reduced
            ? "none"
            : `grid-template-rows 460ms ${MORPH}, opacity ${done ? "180ms" : "320ms"} ${MORPH}`,
        }}
      >
        <div className="min-h-0 overflow-hidden">
          <div className="p-1.5 pt-0">
            <div className="px-2.5 pb-2.5">
              <p
                id={`${id}-q`}
                className="mt-1.5 text-[14px] font-medium leading-snug text-foreground"
              >
                {question}
              </p>
              {detail && (
                <p className="mt-0.5 text-[12.5px] leading-relaxed text-muted-foreground">
                  {detail}
                </p>
              )}
            </div>

            <div
              role={multiple ? "group" : "radiogroup"}
              aria-labelledby={`${id}-q`}
              onKeyDown={onListKey}
              className="relative"
            >
              <span
                aria-hidden="true"
                className="absolute inset-x-0 top-0 rounded-[14px] bg-accent"
                style={{
                  height: highlight.height,
                  transform: `translateY(${highlight.top}px)`,
                  transition:
                    highlight.ready && !reduced
                      ? `transform 200ms ${EASE}, height 200ms ${EASE}`
                      : "none",
                }}
              />
              {rows.map((row, i) => {
                const isOther = row.id === OTHER;
                const checked = isOther ? otherOpen : picked.includes(row.id);
                const description =
                  "description" in row ? row.description : undefined;
                const marker = multiple ? (
                  <span
                    aria-hidden="true"
                    className={`flex size-[18px] shrink-0 items-center justify-center rounded-[6px] transition-[background-color,box-shadow] duration-200 ${
                      checked
                        ? "bg-primary text-primary-foreground"
                        : "shadow-[inset_0_0_0_1.5px_var(--border)]"
                    }`}
                  >
                    <DrawnCheck drawn={checked} reduced={reduced} />
                  </span>
                ) : (
                  <kbd
                    aria-hidden="true"
                    className={`flex size-[18px] shrink-0 items-center justify-center rounded-[6px] font-mono text-[10.5px] transition-colors ${
                      i === active
                        ? "bg-background text-foreground shadow-[0_0_0_1px_var(--border)]"
                        : "text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]"
                    }`}
                  >
                    {i + 1}
                  </kbd>
                );

                if (isOther && otherOpen) {
                  return (
                    <div
                      key={row.id}
                      ref={(el) => {
                        rowRefs.current[i] = el;
                      }}
                      className="relative flex min-h-11 items-center gap-3 rounded-[14px] px-2.5"
                    >
                      {marker}
                      <input
                        ref={otherRef}
                        value={otherText}
                        onChange={(e) => setOtherText(e.target.value)}
                        onFocus={() => setActive(i)}
                        onKeyDown={(e) => {
                          if (e.nativeEvent.isComposing) return;
                          if (e.key === "Enter") {
                            e.preventDefault();
                            submitOther();
                          } else if (e.key === "Escape") {
                            e.preventDefault();
                            setOtherOpen(false);
                            requestAnimationFrame(() =>
                              (
                                rowRefs.current[i] as HTMLElement | null
                              )?.focus(),
                            );
                          }
                        }}
                        placeholder="Type your answer"
                        aria-label={otherLabel}
                        className="h-8 min-w-0 flex-1 bg-transparent text-[13.5px] text-foreground outline-none placeholder:text-muted-foreground animate-[ui-fade-in_200ms_ease-out_both] motion-reduce:animate-none"
                      />
                      {!multiple && (
                        <button
                          type="button"
                          aria-label="Send answer"
                          disabled={!otherText.trim()}
                          onClick={submitOther}
                          className={`cursor-pointer disabled:cursor-default flex size-7 shrink-0 items-center justify-center rounded-full bg-primary text-primary-foreground transition-[opacity,transform] active:scale-[0.94] disabled:opacity-30 ${FOCUS}`}
                        >
                          <ArrowUp className="size-3.5" strokeWidth={2.4} />
                        </button>
                      )}
                    </div>
                  );
                }

                return (
                  <button
                    key={row.id}
                    ref={(el) => {
                      rowRefs.current[i] = el;
                    }}
                    type="button"
                    role={multiple ? "checkbox" : "radio"}
                    aria-checked={multiple ? checked : false}
                    tabIndex={i === active ? 0 : -1}
                    onClick={() => choose(i)}
                    onPointerMove={() => i !== active && setActive(i)}
                    onFocus={() => setActive(i)}
                    className="cursor-pointer relative flex min-h-11 w-full items-center gap-3 rounded-[14px] px-2.5 py-2 text-left outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/30"
                  >
                    {marker}
                    <span className="min-w-0 flex-1">
                      <span
                        className={`block text-[13.5px] ${isOther ? "text-muted-foreground" : "text-foreground"}`}
                      >
                        {isOther ? `${row.label}…` : row.label}
                      </span>
                      {description && (
                        <span className="mt-px block text-[12px] leading-snug text-muted-foreground">
                          {description}
                        </span>
                      )}
                    </span>
                  </button>
                );
              })}
            </div>

            {(onSkip || multiple) && (
              <div className="flex items-center justify-between gap-2 px-1 pb-0.5 pt-1.5">
                {onSkip ? (
                  <button
                    type="button"
                    onClick={skip}
                    className={`cursor-pointer h-8 rounded-full px-2.5 text-[12.5px] text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
                  >
                    Skip
                  </button>
                ) : (
                  <span />
                )}
                {multiple && (
                  <button
                    type="button"
                    disabled={!canContinue}
                    onClick={() =>
                      submit(
                        picked,
                        otherOpen && otherText.trim()
                          ? otherText.trim()
                          : undefined,
                      )
                    }
                    className={`cursor-pointer disabled:cursor-default inline-flex h-8 items-center rounded-full bg-primary px-3.5 text-[12.5px] font-medium text-primary-foreground transition-[opacity,transform] duration-300 active:scale-[0.96] disabled:opacity-35 ${FOCUS}`}
                  >
                    Continue
                    {/* " · 3" opens beside it with the first pick and rolls as you pick more. */}
                    <span
                      aria-hidden="true"
                      className="grid"
                      style={{
                        gridTemplateColumns: count > 0 ? "1fr" : "0fr",
                        opacity: count > 0 ? 1 : 0,
                        transition: reduced
                          ? "none"
                          : `grid-template-columns 380ms ${MORPH}, opacity 260ms ${MORPH}`,
                      }}
                    >
                      <span className="flex min-w-0 items-baseline overflow-hidden whitespace-nowrap tabular-nums">
                        &nbsp;·&nbsp;
                        <NumberRoll value={Math.max(count, 1)} duration={500} />
                      </span>
                    </span>
                    {count > 0 && (
                      <span className="sr-only">, {count} selected</span>
                    )}
                  </button>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}
